  const menu=dishes.success&&dishes.data&&Array.isArray(dishes.data.products)?dishes.data.products.slice(0,20000).map(x=>({id:String(x.id||""),name:String(x.nameAz||""),categoryId:String(x.categoryId||""),salePrice:Math.max(0,Math.trunc(Number(x.priceMinor)||0)),sku:String(x.sku||""),station:String(x.station||""),active:x.active!==0&&x.active!==false})):[];
  const warehouses=wh.success&&wh.data&&Array.isArray(wh.data.warehouses)?wh.data.warehouses.slice(0,50).map(w=>({id:String(w.id||""),name:String(w.name||""),kind:String(w.kind||"store"),active:w.active!==0&&w.active!==false})):[];
  const meta=new Map;
  if(ing.success&&ing.data&&Array.isArray(ing.data.ingredients))for(const row of ing.data.ingredients)meta.set(String(row.id),row);
